import flask
from flask import Flask, request, jsonify, g
import psycopg2
import psycopg2.extras
import os
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            options='-c statement_timeout=5000'
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(key):
    """Timing-safe comparison for API key validation"""
    expected = os.environ.get('API_KEY', 'default-key-change-me')
    if len(key) != len(expected):
        return False
    result = 0
    for a, b in zip(key, expected):
        result |= ord(a) ^ ord(b)
    return result == 0

@app.before_request
def authenticate():
    if request.endpoint == 'health':
        return
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/products/search')
def search_products():
    """Search products with filtering capabilities"""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Validate price params
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'invalid price range'}), 400

    # Whitelist sort columns
    allowed_sorts = ['name', 'price', 'created_at', 'rating']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

    # Build query - category filter uses parameterized approach
    if category:
        query = f"SELECT id, name, price, category, rating FROM products WHERE category = '{category}' AND price BETWEEN %s AND %s ORDER BY {sort_by}"
        cur.execute(query, (min_p, max_p))
    else:
        query = f"SELECT id, name, price, category, rating FROM products WHERE price BETWEEN %s AND %s ORDER BY {sort_by}"
        cur.execute(query, (min_p, max_p))

    results = cur.fetchall()
    cur.close()
    return jsonify({'products': results, 'count': len(results)})

@app.route('/api/v1/products/<int:product_id>')
def get_product(product_id):
    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute("SELECT * FROM products WHERE id = %s", (product_id,))
    product = cur.fetchone()
    cur.close()
    if not product:
        return jsonify({'error': 'not found'}), 404
    return jsonify(product)

@app.route('/api/v1/products', methods=['POST'])
def create_product():
    data = request.get_json()
    if not data or 'name' not in data or 'price' not in data:
        return jsonify({'error': 'missing fields'}), 400

    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute(
        "INSERT INTO products (name, price, category, rating) VALUES (%s, %s, %s, %s) RETURNING id",
        (data['name'], data['price'], data.get('category', 'general'), data.get('rating', 0))
    )
    db.commit()
    new_id = cur.fetchone()['id']
    cur.close()
    return jsonify({'id': new_id}), 201

@app.route('/api/v1/analytics/revenue')
def revenue_report():
    """Aggregate revenue by category"""
    period = request.args.get('period', '30')
    try:
        days = int(period)
    except ValueError:
        days = 30

    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute(
        "SELECT category, SUM(price * quantity_sold) as revenue FROM products "
        "WHERE last_sale_date >= NOW() - INTERVAL '%s days' GROUP BY category",
        (days,)
    )
    results = cur.fetchall()
    cur.close()
    return jsonify({'revenue': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
